import{_ as o,W as l,s as d,u as r,ah as n,I as s,Z as i,w as p,A as e}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const c=JSON.parse('{"title":"使用 Pip 升级 Python 软件包 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Pip 升级 Python 软件包 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"使用 Pip 升级 Python 软件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Pip 升级 Python 软件包 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221027.0 ⭐️ How to Upgrade Python Packages with Pip","title":"使用 Pip 升级 Python 软件包","tag":"202211"},"relativePath":"202211/20221027.0 ⭐️ How to Upgrade Python Packages with Pip.md","filePath":"[post].md"}'),h={name:"202211/20221027.0 ⭐️ How to Upgrade Python Packages with Pip.md"};function g(u,t,m,P,b,y){const a=l("Link");return r(),d("div",null,[t[26]||(t[26]=n('<h1 id="使用-pip-升级-python-软件包" tabindex="-1">使用 Pip 升级 Python 软件包 <a class="header-anchor" href="#使用-pip-升级-python-软件包" aria-label="Permalink to 使用 Pip 升级 Python 软件包">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/07/153408lqflbw3mwxja3qm4.jpg" alt=""></p><p>你上次更新通过 Pip 安装的 Python 软件包是什么时候？大多数用户往往会忘记这些 Python 软件包也需要手动更新，因为仅仅更新系统存储库对于软件包来说是不起作用的。</p><p>因此，让我们花点时间看看如何使用 Pip，来更新旧的 Python 软件包吧。</p><h3 id="如何使用-pip-升级-python-软件包" tabindex="-1">如何使用 Pip 升级 Python 软件包 <a class="header-anchor" href="#如何使用-pip-升级-python-软件包" aria-label="Permalink to 如何使用 Pip 升级 Python 软件包">​</a></h3>',5)),s("p",null,[i(a,{href:"https://itsfoss.com/install-pip-ubuntu/"},{default:e(()=>t[0]||(t[0]=[p("Pip（Pip Installs Packages）")])),_:1}),t[1]||(t[1]=p(" 是一个用于管理 Python 软件包的 ")),t[2]||(t[2]=s("ruby",null,[p("命令行实用程序 "),s("rt",null," command line utility ")],-1)),t[3]||(t[3]=p(" 。你可以将 Pip 安装 Python 软件包，类比为在 Ubuntu 和 Debian 中使用 ")),t[4]||(t[4]=s("code",null,"apt",-1)),t[5]||(t[5]=p(" 管理软件包那样。"))]),t[27]||(t[27]=n('<p>因此，接下来就让我们深入了解如何使用这个极好的工具 Pip，来管理与 Python 软件包相关的内容吧。</p><h4 id="_1、列出过时的-python-软件包" tabindex="-1">1、列出过时的 Python 软件包 <a class="header-anchor" href="#_1、列出过时的-python-软件包" aria-label="Permalink to 1、列出过时的 Python 软件包">​</a></h4><p>在计划更新什么软件包之前，我们先要列出有哪些过时的软件包，你可以在其中选择想要更新的软件包，因为大多数人不会想一下子更新整个软件包库。</p><p>要列出过时的 Python 软件包，你只需将 <code>pip</code> 命令与 <code>list</code> 选项、<code>--outdated</code> 标志一同使用即可，如下图所示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip list --outdated</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/outdated-packages.png" alt="outdated packages"></p><h4 id="_2、升级特定的软件包" tabindex="-1">2、升级特定的软件包 <a class="header-anchor" href="#_2、升级特定的软件包" aria-label="Permalink to 2、升级特定的软件包">​</a></h4><p>获得可更新的软件包列表后，你可以像我之前提到的那样，选择你要更新的那个特定的软件包，pip 升级软件包命令的语法如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip install package_name -U</span></span></code></pre></div><p>例如，我想将名为 <code>anime-api</code> 的软件包升级到最新版本，所以我将使用下面的命令来升级：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip install anime-api -U</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/update-anime-api.png" alt="update anime api"></p><h4 id="_3、将软件包升级到特定的版本" tabindex="-1">3、将软件包升级到特定的版本 <a class="header-anchor" href="#_3、将软件包升级到特定的版本" aria-label="Permalink to 3、将软件包升级到特定的版本">​</a></h4><p>没有必要总是使用软件的最新版本，如果你想将软件包升级到不是最新的某个特定版本，参考如下的命令语法：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip install --upgrade &lt;package&gt;==&lt;version&gt;</span></span></code></pre></div><p>例如，我想将名为 <code>xdg</code> 的软件包更新到 5.1 版本，5.1 版本是最新版本的前一个版本，所以可以使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip install --upgrade xdg==5.1</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/upgrade-xdg-to-specific-iteration.png" alt="upgrade xdg to specific iteration"></p><h4 id="_4、使用-pip-一次性升级所有软件包" tabindex="-1">4、使用 Pip 一次性升级所有软件包 <a class="header-anchor" href="#_4、使用-pip-一次性升级所有软件包" aria-label="Permalink to 4、使用 Pip 一次性升级所有软件包">​</a></h4><p><strong>请注意：我不建议你一次性升级所以软件包，因为 Python 软件包的依赖项太复杂了，一次性的升级无法处理相互依赖项。</strong></p><p>要一次性升级所有 python 软件包，你可以使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip3 list --outdated --format=freeze | grep -v &#39;^\\-e&#39; | cut -d = -f 1 | xargs -n1 pip3 install -U</span></span></code></pre></div><p><img src="https://itsfoss.com/wp-content/uploads/2022/09/upgrade-everything.png" alt="upgrade everything"></p>',23)),s("p",null,[t[7]||(t[7]=p("上面的命令使用了 ")),i(a,{href:"https://linuxhandbook.com/xargs-command/"},{default:e(()=>t[6]||(t[6]=[p("xargs")])),_:1}),t[8]||(t[8]=p("。首先，会得到所有需要更新的软件包，然后对每个软件包执行 ")),t[9]||(t[9]=s("code",null,"pip3 install -U",-1)),t[10]||(t[10]=p(" 命令。"))]),t[28]||(t[28]=n('<p>我在这里使用的是 <code>pip3</code>，而不是 <code>pip</code>。在 Ubuntu 22.04 及更高的版本中，<code>pip</code> 和 <code>pip3</code> 命令都可以使用。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h3><p>使用 Pip 一次性更新所有 Python 软件包并不是一个好主意。我发现一次性更新后，软件包之间的依赖关系被破坏了，所以请确保只更新你想要更新的软件包。</p><p>如果你还有其他的疑问，就请在评论区中留言吧。</p><hr>',5)),s("p",null,[t[12]||(t[12]=p("via: ")),i(a,{href:"https://itsfoss.com/upgrade-pip-packages/"},{default:e(()=>t[11]||(t[11]=[p("https://itsfoss.com/upgrade-pip-packages/")])),_:1})]),s("p",null,[t[17]||(t[17]=p("作者：")),i(a,{href:"https://itsfoss.com/author/sagar/"},{default:e(()=>t[13]||(t[13]=[p("Sagar Sharma")])),_:1}),t[18]||(t[18]=p(" 选题：")),i(a,{href:"https://github.com/lkxed"},{default:e(()=>t[14]||(t[14]=[p("lkxed")])),_:1}),t[19]||(t[19]=p(" 译者：")),i(a,{href:"https://github.com/chai001125"},{default:e(()=>t[15]||(t[15]=[p("chai001125")])),_:1}),t[20]||(t[20]=p(" 校对：")),i(a,{href:"https://github.com/wxy"},{default:e(()=>t[16]||(t[16]=[p("wxy")])),_:1})]),s("p",null,[t[23]||(t[23]=p("本文由 ")),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>t[21]||(t[21]=[p("LCTT")])),_:1}),t[24]||(t[24]=p(" 原创编译，")),i(a,{href:"https://linux.cn/"},{default:e(()=>t[22]||(t[22]=[p("Linux中国")])),_:1}),t[25]||(t[25]=p(" 荣誉推出"))])])}const v=o(h,[["render",g]]);export{c as __pageData,v as default};
